int RspQryCapitalPackage::ToStepStream(char* buff, int size) const
{
	StepWriteCursor cursor(buff, size);
	if (Capital != nullptr)
	{
		StepUtility::WriteHexString(cursor, Items::FieldStart, CapitalField::FieldId);
		if (strlen(Capital->TradingDay) >= sizeof(Capital->TradingDay))
		{
			Capital->TradingDay[sizeof(Capital->TradingDay) - 1] = 0;
		}
		StepUtility::WriteString(cursor, Items::TradingDay, Capital->TradingDay);
		if (strlen(Capital->AccountId) >= sizeof(Capital->AccountId))
		{
			Capital->AccountId[sizeof(Capital->AccountId) - 1] = 0;
		}
		StepUtility::WriteString(cursor, Items::AccountId, Capital->AccountId);
		StepUtility::WriteString(cursor, Items::AccountType, static_cast<int>(Capital->AccountType));
		StepUtility::WriteString(cursor, Items::Asset, Capital->Asset);
		StepUtility::WriteString(cursor, Items::PreAsset, Capital->PreAsset);
		StepUtility::WriteString(cursor, Items::CashAsset, Capital->CashAsset);
		StepUtility::WriteString(cursor, Items::PreCashAsset, Capital->PreCashAsset);
		StepUtility::WriteString(cursor, Items::Available, Capital->Available);
		StepUtility::WriteString(cursor, Items::CashIn, Capital->CashIn);
		StepUtility::WriteString(cursor, Items::CashOut, Capital->CashOut);
		StepUtility::WriteString(cursor, Items::Margin, Capital->Margin);
		StepUtility::WriteString(cursor, Items::Commission, Capital->Commission);
		StepUtility::WriteString(cursor, Items::StampTax, Capital->StampTax);
		StepUtility::WriteString(cursor, Items::TransferFee, Capital->TransferFee);
		StepUtility::WriteString(cursor, Items::FrozenCash, Capital->FrozenCash);
		StepUtility::WriteString(cursor, Items::FrozenMargin, Capital->FrozenMargin);
		StepUtility::WriteString(cursor, Items::FrozenCommission, Capital->FrozenCommission);
		StepUtility::WriteString(cursor, Items::FrozenStampTax, Capital->FrozenStampTax);
		StepUtility::WriteString(cursor, Items::FrozenTransferFee, Capital->FrozenTransferFee);
		StepUtility::WriteString(cursor, Items::MarketValue, Capital->MarketValue);
		StepUtility::WriteString(cursor, Items::TotalProfit, Capital->TotalProfit);
		StepUtility::WriteString(cursor, Items::TodayProfit, Capital->TodayProfit);
		StepUtility::WriteString(cursor, Items::Deposit, Capital->Deposit);
		StepUtility::WriteString(cursor, Items::Withdraw, Capital->Withdraw);
		StepUtility::WriteHexString(cursor, Items::FieldEnd, CapitalField::FieldId);
	}
	if (RspInfo != nullptr)
	{
		StepUtility::WriteHexString(cursor, Items::FieldStart, RspInfoField::FieldId);
		StepUtility::WriteString(cursor, Items::ErrorId, RspInfo->ErrorId);
		if (strlen(RspInfo->ErrorMsg) >= sizeof(RspInfo->ErrorMsg))
		{
			RspInfo->ErrorMsg[sizeof(RspInfo->ErrorMsg) - 1] = 0;
		}
		StepUtility::WriteString(cursor, Items::ErrorMsg, RspInfo->ErrorMsg);
		StepUtility::WriteHexString(cursor, Items::FieldEnd, RspInfoField::FieldId);
	}
	if (cursor.IsTruncated())
	{
		return -1;
	}
	return cursor.GetWrittenLength();
}
bool RspQryCapitalPackage::FromStepStream(char* buff, int startIndex, int endIndex)
{
	while (startIndex < endIndex)
	{
		unsigned short fieldId;
		int fieldStartIndex;
		int fieldEndIndex;
		if (StepUtility::GetNextFieldZone(buff, startIndex, endIndex, fieldId, fieldStartIndex, fieldEndIndex))
		{
			int itemStartIndex = fieldStartIndex;
			switch (fieldId)
			{
			case CapitalField::FieldId:
			{
				Capital = ObjectPool<CapitalField>::GetInstance().Allocate();
				memset(Capital, 0, sizeof(*Capital));
				while (itemStartIndex < fieldEndIndex)
				{
					unsigned short  itemId;
					std::string value;
					int sohIndex;
					if (StepUtility::GetNext(buff, itemStartIndex, fieldEndIndex, itemId, value, sohIndex))
					{
						switch (itemId)
						{
						case Items::FieldStart:
						case Items::FieldEnd:
							break;
						case Items::TradingDay:
						{
							if (value.length() >= sizeof(Capital->TradingDay))
							{
								WriteLog(LogLevel::Warning, "TradingDay Out Of Range. Length:%zu, Capacity:%zu", value.length(), sizeof(Capital->TradingDay) - 1);
								return false;
							}
							memcpy(Capital->TradingDay, value.c_str(), value.length());
							break;
						}
						case Items::AccountId:
						{
							if (value.length() >= sizeof(Capital->AccountId))
							{
								WriteLog(LogLevel::Warning, "AccountId Out Of Range. Length:%zu, Capacity:%zu", value.length(), sizeof(Capital->AccountId) - 1);
								return false;
							}
							memcpy(Capital->AccountId, value.c_str(), value.length());
							break;
						}
						case Items::AccountType:
						{
							if (!StepUtility::ParseEnum(value, Capital->AccountType))
							{
								WriteLog(LogLevel::Warning, "AccountType Out Of Range. Value:%s", value.c_str());
								return false;
							}
							break;
						}
						case Items::Asset:
						{
							if (!StepUtility::ParseDouble(value, Capital->Asset))
							{
								WriteLog(LogLevel::Warning, "Asset Out Of Range. Value:%s", value.c_str());
								return false;
							}
							break;
						}
						case Items::PreAsset:
						{
							if (!StepUtility::ParseDouble(value, Capital->PreAsset))
							{
								WriteLog(LogLevel::Warning, "PreAsset Out Of Range. Value:%s", value.c_str());
								return false;
							}
							break;
						}
						case Items::CashAsset:
						{
							if (!StepUtility::ParseDouble(value, Capital->CashAsset))
							{
								WriteLog(LogLevel::Warning, "CashAsset Out Of Range. Value:%s", value.c_str());
								return false;
							}
							break;
						}
						case Items::PreCashAsset:
						{
							if (!StepUtility::ParseDouble(value, Capital->PreCashAsset))
							{
								WriteLog(LogLevel::Warning, "PreCashAsset Out Of Range. Value:%s", value.c_str());
								return false;
							}
							break;
						}
						case Items::Available:
						{
							if (!StepUtility::ParseDouble(value, Capital->Available))
							{
								WriteLog(LogLevel::Warning, "Available Out Of Range. Value:%s", value.c_str());
								return false;
							}
							break;
						}
						case Items::CashIn:
						{
							if (!StepUtility::ParseDouble(value, Capital->CashIn))
							{
								WriteLog(LogLevel::Warning, "CashIn Out Of Range. Value:%s", value.c_str());
								return false;
							}
							break;
						}
						case Items::CashOut:
						{
							if (!StepUtility::ParseDouble(value, Capital->CashOut))
							{
								WriteLog(LogLevel::Warning, "CashOut Out Of Range. Value:%s", value.c_str());
								return false;
							}
							break;
						}
						case Items::Margin:
						{
							if (!StepUtility::ParseDouble(value, Capital->Margin))
							{
								WriteLog(LogLevel::Warning, "Margin Out Of Range. Value:%s", value.c_str());
								return false;
							}
							break;
						}
						case Items::Commission:
						{
							if (!StepUtility::ParseDouble(value, Capital->Commission))
							{
								WriteLog(LogLevel::Warning, "Commission Out Of Range. Value:%s", value.c_str());
								return false;
							}
							break;
						}
						case Items::StampTax:
						{
							if (!StepUtility::ParseDouble(value, Capital->StampTax))
							{
								WriteLog(LogLevel::Warning, "StampTax Out Of Range. Value:%s", value.c_str());
								return false;
							}
							break;
						}
						case Items::TransferFee:
						{
							if (!StepUtility::ParseDouble(value, Capital->TransferFee))
							{
								WriteLog(LogLevel::Warning, "TransferFee Out Of Range. Value:%s", value.c_str());
								return false;
							}
							break;
						}
						case Items::FrozenCash:
						{
							if (!StepUtility::ParseDouble(value, Capital->FrozenCash))
							{
								WriteLog(LogLevel::Warning, "FrozenCash Out Of Range. Value:%s", value.c_str());
								return false;
							}
							break;
						}
						case Items::FrozenMargin:
						{
							if (!StepUtility::ParseDouble(value, Capital->FrozenMargin))
							{
								WriteLog(LogLevel::Warning, "FrozenMargin Out Of Range. Value:%s", value.c_str());
								return false;
							}
							break;
						}
						case Items::FrozenCommission:
						{
							if (!StepUtility::ParseDouble(value, Capital->FrozenCommission))
							{
								WriteLog(LogLevel::Warning, "FrozenCommission Out Of Range. Value:%s", value.c_str());
								return false;
							}
							break;
						}
						case Items::FrozenStampTax:
						{
							if (!StepUtility::ParseDouble(value, Capital->FrozenStampTax))
							{
								WriteLog(LogLevel::Warning, "FrozenStampTax Out Of Range. Value:%s", value.c_str());
								return false;
							}
							break;
						}
						case Items::FrozenTransferFee:
						{
							if (!StepUtility::ParseDouble(value, Capital->FrozenTransferFee))
							{
								WriteLog(LogLevel::Warning, "FrozenTransferFee Out Of Range. Value:%s", value.c_str());
								return false;
							}
							break;
						}
						case Items::MarketValue:
						{
							if (!StepUtility::ParseDouble(value, Capital->MarketValue))
							{
								WriteLog(LogLevel::Warning, "MarketValue Out Of Range. Value:%s", value.c_str());
								return false;
							}
							break;
						}
						case Items::TotalProfit:
						{
							if (!StepUtility::ParseDouble(value, Capital->TotalProfit))
							{
								WriteLog(LogLevel::Warning, "TotalProfit Out Of Range. Value:%s", value.c_str());
								return false;
							}
							break;
						}
						case Items::TodayProfit:
						{
							if (!StepUtility::ParseDouble(value, Capital->TodayProfit))
							{
								WriteLog(LogLevel::Warning, "TodayProfit Out Of Range. Value:%s", value.c_str());
								return false;
							}
							break;
						}
						case Items::Deposit:
						{
							if (!StepUtility::ParseDouble(value, Capital->Deposit))
							{
								WriteLog(LogLevel::Warning, "Deposit Out Of Range. Value:%s", value.c_str());
								return false;
							}
							break;
						}
						case Items::Withdraw:
						{
							if (!StepUtility::ParseDouble(value, Capital->Withdraw))
							{
								WriteLog(LogLevel::Warning, "Withdraw Out Of Range. Value:%s", value.c_str());
								return false;
							}
							break;
						}
						default:
							WriteLog(LogLevel::Warning, "Unexpected ItemId:0x%X for CapitalField FieldId:0x%X, Please Check ApiVersion.", itemId, fieldId);
							return false;
						}
						itemStartIndex = sohIndex + 1;
					}
					else
					{
						WriteLog(LogLevel::Warning, "GetNext Failed For RspQryCapitalPackage FieldId:0x%X", fieldId);
						return false;
					}
				}
				break;
			}
			case RspInfoField::FieldId:
			{
				RspInfo = ObjectPool<RspInfoField>::GetInstance().Allocate();
				memset(RspInfo, 0, sizeof(*RspInfo));
				while (itemStartIndex < fieldEndIndex)
				{
					unsigned short  itemId;
					std::string value;
					int sohIndex;
					if (StepUtility::GetNext(buff, itemStartIndex, fieldEndIndex, itemId, value, sohIndex))
					{
						switch (itemId)
						{
						case Items::FieldStart:
						case Items::FieldEnd:
							break;
						case Items::ErrorId:
						{
							if (!StepUtility::ParseInteger(value, RspInfo->ErrorId))
							{
								WriteLog(LogLevel::Warning, "ErrorId Out Of Range. Value:%s", value.c_str());
								return false;
							}
							break;
						}
						case Items::ErrorMsg:
						{
							if (value.length() >= sizeof(RspInfo->ErrorMsg))
							{
								WriteLog(LogLevel::Warning, "ErrorMsg Out Of Range. Length:%zu, Capacity:%zu", value.length(), sizeof(RspInfo->ErrorMsg) - 1);
								return false;
							}
							memcpy(RspInfo->ErrorMsg, value.c_str(), value.length());
							break;
						}
						default:
							WriteLog(LogLevel::Warning, "Unexpected ItemId:0x%X for RspInfoField FieldId:0x%X, Please Check ApiVersion.", itemId, fieldId);
							return false;
						}
						itemStartIndex = sohIndex + 1;
					}
					else
					{
						WriteLog(LogLevel::Warning, "GetNext Failed For RspQryCapitalPackage FieldId:0x%X", fieldId);
						return false;
					}
				}
				break;
			}
			default:
				WriteLog(LogLevel::Warning, "Unexpected FieldId:0x%X, Please Check Api Version.", fieldId);
				return false;
			}
			startIndex = fieldEndIndex;
		}
		else
		{
			WriteLog(LogLevel::Warning, "GetNextFieldZone Failed For RspQryCapitalPackage");
			return false;
		}
	}
	return true;
}
int RspQryCapitalPackage::ToXtpStream(char* buff, int size) const
{
	int offset = 0;
	if (Capital != nullptr)
	{
		const int fieldSize = static_cast<int>(sizeof(UInt16Type) + sizeof(CapitalField));
		if (offset + fieldSize > size)
		{
			return -1;
		}
		memcpy(buff + offset, &CapitalField::FieldId, sizeof(UInt16Type));
		offset += sizeof(UInt16Type);
		memcpy(buff + offset, Capital, sizeof(CapitalField));
		offset += sizeof(CapitalField);
	}
	if (RspInfo != nullptr)
	{
		const int fieldSize = static_cast<int>(sizeof(UInt16Type) + sizeof(RspInfoField));
		if (offset + fieldSize > size)
		{
			return -1;
		}
		memcpy(buff + offset, &RspInfoField::FieldId, sizeof(UInt16Type));
		offset += sizeof(UInt16Type);
		memcpy(buff + offset, RspInfo, sizeof(RspInfoField));
		offset += sizeof(RspInfoField);
	}
	return offset;
}
bool RspQryCapitalPackage::FromXtpStream(char* buff, int startIndex, int endIndex)
{
	int offset = startIndex;
	while(offset < endIndex)
	{
		UInt16Type fieldId = 0;
		memcpy(&fieldId, buff + offset, sizeof(UInt16Type));
		offset += sizeof(UInt16Type);
		switch (fieldId)
		{
		case CapitalField::FieldId:
		{
			Capital = ObjectPool<CapitalField>::GetInstance().Allocate();
			memcpy(Capital, buff + offset, sizeof(CapitalField));
			offset += sizeof(CapitalField);	
			break;
		}
		case RspInfoField::FieldId:
		{
			RspInfo = ObjectPool<RspInfoField>::GetInstance().Allocate();
			memcpy(RspInfo, buff + offset, sizeof(RspInfoField));
			offset += sizeof(RspInfoField);	
			break;
		}
		default:
			return false;
		}
	}
	return offset == endIndex;
}
const char* RspQryCapitalPackage::GetDebugString() const
{
	int offset = 0;
	if (Capital != nullptr)
	{
		offset = AppendDebugString(offset, "Capital:TradingDay:[%s], AccountId:[%s], AccountType:[%d], Asset:[%f], PreAsset:[%f], CashAsset:[%f], PreCashAsset:[%f], Available:[%f], CashIn:[%f], CashOut:[%f], Margin:[%f], Commission:[%f], StampTax:[%f], TransferFee:[%f], FrozenCash:[%f], FrozenMargin:[%f], FrozenCommission:[%f], FrozenStampTax:[%f], FrozenTransferFee:[%f], MarketValue:[%f], TotalProfit:[%f], TodayProfit:[%f], Deposit:[%f], Withdraw:[%f]", Capital->TradingDay, Capital->AccountId, static_cast<int>(Capital->AccountType), Capital->Asset, Capital->PreAsset, Capital->CashAsset, Capital->PreCashAsset, Capital->Available, Capital->CashIn, Capital->CashOut, Capital->Margin, Capital->Commission, Capital->StampTax, Capital->TransferFee, Capital->FrozenCash, Capital->FrozenMargin, Capital->FrozenCommission, Capital->FrozenStampTax, Capital->FrozenTransferFee, Capital->MarketValue, Capital->TotalProfit, Capital->TodayProfit, Capital->Deposit, Capital->Withdraw);
	}
	if (RspInfo != nullptr)
	{
		offset = AppendDebugString(offset, "RspInfo:ErrorId:[%d], ErrorMsg:[%s]", RspInfo->ErrorId, RspInfo->ErrorMsg);
	}
	return DataStringBuffer;
}
 
