int RspQryPositionPackage::ToXtpStream(char* buff, int size) const
{
	int offset = 0;
	if (Position != nullptr)
	{
		const int fieldSize = static_cast<int>(sizeof(UInt16Type) + sizeof(PositionField));
		if (offset + fieldSize > size)
		{
			return -1;
		}
		memcpy(buff + offset, &PositionField::FieldId, sizeof(UInt16Type));
		offset += sizeof(UInt16Type);
		memcpy(buff + offset, Position, sizeof(PositionField));
		offset += sizeof(PositionField);
	}
	if (RspInfo != nullptr)
	{
		const int fieldSize = static_cast<int>(sizeof(UInt16Type) + sizeof(RspInfoField));
		if (offset + fieldSize > size)
		{
			return -1;
		}
		memcpy(buff + offset, &RspInfoField::FieldId, sizeof(UInt16Type));
		offset += sizeof(UInt16Type);
		memcpy(buff + offset, RspInfo, sizeof(RspInfoField));
		offset += sizeof(RspInfoField);
	}
	return offset;
}
bool RspQryPositionPackage::FromXtpStream(char* buff, int startIndex, int endIndex)
{
	int offset = startIndex;
	while(offset < endIndex)
	{
		UInt16Type fieldId = 0;
		memcpy(&fieldId, buff + offset, sizeof(UInt16Type));
		offset += sizeof(UInt16Type);
		switch (fieldId)
		{
		case PositionField::FieldId:
		{
			Position = ObjectPool<PositionField>::GetInstance().Allocate();
			memcpy(Position, buff + offset, sizeof(PositionField));
			offset += sizeof(PositionField);	
			break;
		}
		case RspInfoField::FieldId:
		{
			RspInfo = ObjectPool<RspInfoField>::GetInstance().Allocate();
			memcpy(RspInfo, buff + offset, sizeof(RspInfoField));
			offset += sizeof(RspInfoField);	
			break;
		}
		default:
			return false;
		}
	}
	return offset == endIndex;
}
const char* RspQryPositionPackage::GetDebugString() const
{
	int offset = 0;
	if (Position != nullptr)
	{
		offset = AppendDebugString(offset, "Position:TradingDay:[%s], AccountId:[%s], AccountType:[%d], ExchangeId:[%s], InstrumentId:[%s], ProductClass:[%d], PosiDirection:[%d], TotalPosition:[%lld], PositionFrozen:[%lld], TodayPosition:[%lld], TotalCostPrice:[%f], TodayCostPrice:[%f], CashIn:[%f], CashOut:[%f], Margin:[%f], Commission:[%f], StampTax:[%f], TransferFee:[%f], MarketValue:[%f], VolumeMultiple:[%d], TotalCost:[%f], TodayCost:[%f], TotalProfit:[%f], TodayProfit:[%f], LastPrice:[%f], PrePrice:[%f]", Position->TradingDay, Position->AccountId, static_cast<int>(Position->AccountType), Position->ExchangeId, Position->InstrumentId, static_cast<int>(Position->ProductClass), static_cast<int>(Position->PosiDirection), Position->TotalPosition, Position->PositionFrozen, Position->TodayPosition, Position->TotalCostPrice, Position->TodayCostPrice, Position->CashIn, Position->CashOut, Position->Margin, Position->Commission, Position->StampTax, Position->TransferFee, Position->MarketValue, Position->VolumeMultiple, Position->TotalCost, Position->TodayCost, Position->TotalProfit, Position->TodayProfit, Position->LastPrice, Position->PrePrice);
	}
	if (RspInfo != nullptr)
	{
		offset = AppendDebugString(offset, "RspInfo:ErrorId:[%d], ErrorMsg:[%s]", RspInfo->ErrorId, RspInfo->ErrorMsg);
	}
	return DataStringBuffer;
}
 
