bool RspQryInstrumentPackage::FromStepStream(char* buff, int startIndex, int endIndex)
{
	while (startIndex < endIndex)
	{
		unsigned short fieldId;
		int fieldStartIndex;
		int fieldEndIndex;
		if (StepUtility::GetNextFieldZone(buff, startIndex, endIndex, fieldId, fieldStartIndex, fieldEndIndex))
		{
			int itemStartIndex = fieldStartIndex;
			switch (fieldId)
			{
			case InstrumentField::FieldId:
			{
				Instrument = ObjectPool<InstrumentField>::GetInstance().Allocate();
				memset(Instrument, 0, sizeof(*Instrument));
				while (itemStartIndex < fieldEndIndex)
				{
					unsigned short  itemId;
					std::string value;
					int sohIndex;
					if (StepUtility::GetNext(buff, itemStartIndex, fieldEndIndex, itemId, value, sohIndex))
					{
						switch (itemId)
						{
						case Items::FieldStart:
						case Items::FieldEnd:
							break;
						case Items::ExchangeId:
						{
							if (value.length() >= sizeof(Instrument->ExchangeId))
							{
								WriteLog(LogLevel::Warning, "ExchangeId Out Of Range. Length:%zu, Capacity:%zu", value.length(), sizeof(Instrument->ExchangeId) - 1);
								return false;
							}
							memcpy(Instrument->ExchangeId, value.c_str(), value.length());
							break;
						}
						case Items::InstrumentId:
						{
							if (value.length() >= sizeof(Instrument->InstrumentId))
							{
								WriteLog(LogLevel::Warning, "InstrumentId Out Of Range. Length:%zu, Capacity:%zu", value.length(), sizeof(Instrument->InstrumentId) - 1);
								return false;
							}
							memcpy(Instrument->InstrumentId, value.c_str(), value.length());
							break;
						}
						case Items::ExchangeInstId:
						{
							if (value.length() >= sizeof(Instrument->ExchangeInstId))
							{
								WriteLog(LogLevel::Warning, "ExchangeInstId Out Of Range. Length:%zu, Capacity:%zu", value.length(), sizeof(Instrument->ExchangeInstId) - 1);
								return false;
							}
							memcpy(Instrument->ExchangeInstId, value.c_str(), value.length());
							break;
						}
						case Items::InstrumentName:
						{
							if (value.length() >= sizeof(Instrument->InstrumentName))
							{
								WriteLog(LogLevel::Warning, "InstrumentName Out Of Range. Length:%zu, Capacity:%zu", value.length(), sizeof(Instrument->InstrumentName) - 1);
								return false;
							}
							memcpy(Instrument->InstrumentName, value.c_str(), value.length());
							break;
						}
						case Items::VolumeMultiple:
						{
							if (!StepUtility::ParseInteger(value, Instrument->VolumeMultiple))
							{
								WriteLog(LogLevel::Warning, "VolumeMultiple Out Of Range. Value:%s", value.c_str());
								return false;
							}
							break;
						}
						case Items::ProductClass:
						{
							if (!StepUtility::ParseEnum(value, Instrument->ProductClass))
							{
								WriteLog(LogLevel::Warning, "ProductClass Out Of Range. Value:%s", value.c_str());
								return false;
							}
							break;
						}
						default:
							WriteLog(LogLevel::Warning, "Unexpected ItemId:0x%X for InstrumentField FieldId:0x%X, Please Check ApiVersion.", itemId, fieldId);
							return false;
						}
						itemStartIndex = sohIndex + 1;
					}
					else
					{
						WriteLog(LogLevel::Warning, "GetNext Failed For RspQryInstrumentPackage FieldId:0x%X", fieldId);
						return false;
					}
				}
				break;
			}
			case RspInfoField::FieldId:
			{
				RspInfo = ObjectPool<RspInfoField>::GetInstance().Allocate();
				memset(RspInfo, 0, sizeof(*RspInfo));
				while (itemStartIndex < fieldEndIndex)
				{
					unsigned short  itemId;
					std::string value;
					int sohIndex;
					if (StepUtility::GetNext(buff, itemStartIndex, fieldEndIndex, itemId, value, sohIndex))
					{
						switch (itemId)
						{
						case Items::FieldStart:
						case Items::FieldEnd:
							break;
						case Items::ErrorId:
						{
							if (!StepUtility::ParseInteger(value, RspInfo->ErrorId))
							{
								WriteLog(LogLevel::Warning, "ErrorId Out Of Range. Value:%s", value.c_str());
								return false;
							}
							break;
						}
						case Items::ErrorMsg:
						{
							if (value.length() >= sizeof(RspInfo->ErrorMsg))
							{
								WriteLog(LogLevel::Warning, "ErrorMsg Out Of Range. Length:%zu, Capacity:%zu", value.length(), sizeof(RspInfo->ErrorMsg) - 1);
								return false;
							}
							memcpy(RspInfo->ErrorMsg, value.c_str(), value.length());
							break;
						}
						default:
							WriteLog(LogLevel::Warning, "Unexpected ItemId:0x%X for RspInfoField FieldId:0x%X, Please Check ApiVersion.", itemId, fieldId);
							return false;
						}
						itemStartIndex = sohIndex + 1;
					}
					else
					{
						WriteLog(LogLevel::Warning, "GetNext Failed For RspQryInstrumentPackage FieldId:0x%X", fieldId);
						return false;
					}
				}
				break;
			}
			default:
				WriteLog(LogLevel::Warning, "Unexpected FieldId:0x%X, Please Check Api Version.", fieldId);
				return false;
			}
			startIndex = fieldEndIndex;
		}
		else
		{
			WriteLog(LogLevel::Warning, "GetNextFieldZone Failed For RspQryInstrumentPackage");
			return false;
		}
	}
	return true;
}
