int ReqRiskInsertOrderPackage::ToXtpStream(char* buff, int size) const
{
	int offset = 0;
	if (ReqRiskInsertOrder != nullptr)
	{
		const int fieldSize = static_cast<int>(sizeof(UInt16Type) + sizeof(ReqRiskInsertOrderField));
		if (offset + fieldSize > size)
		{
			return -1;
		}
		memcpy(buff + offset, &ReqRiskInsertOrderField::FieldId, sizeof(UInt16Type));
		offset += sizeof(UInt16Type);
		memcpy(buff + offset, ReqRiskInsertOrder, sizeof(ReqRiskInsertOrderField));
		offset += sizeof(ReqRiskInsertOrderField);
	}
	return offset;
}
bool ReqRiskInsertOrderPackage::FromXtpStream(char* buff, int startIndex, int endIndex)
{
	int offset = startIndex;
	while(offset < endIndex)
	{
		UInt16Type fieldId = 0;
		memcpy(&fieldId, buff + offset, sizeof(UInt16Type));
		offset += sizeof(UInt16Type);
		switch (fieldId)
		{
		case ReqRiskInsertOrderField::FieldId:
		{
			ReqRiskInsertOrder = ObjectPool<ReqRiskInsertOrderField>::GetInstance().Allocate();
			memcpy(ReqRiskInsertOrder, buff + offset, sizeof(ReqRiskInsertOrderField));
			offset += sizeof(ReqRiskInsertOrderField);	
			break;
		}
		default:
			return false;
		}
	}
	return offset == endIndex;
}
