bool RtnExchangeStatusPackage::FromStepStream(char* buff, int startIndex, int endIndex)
{
	while (startIndex < endIndex)
	{
		unsigned short fieldId;
		int fieldStartIndex;
		int fieldEndIndex;
		if (StepUtility::GetNextFieldZone(buff, startIndex, endIndex, fieldId, fieldStartIndex, fieldEndIndex))
		{
			int itemStartIndex = fieldStartIndex;
			switch (fieldId)
			{
			case RtnExchangeStatusField::FieldId:
			{
				RtnExchangeStatus = ObjectPool<RtnExchangeStatusField>::GetInstance().Allocate();
				memset(RtnExchangeStatus, 0, sizeof(*RtnExchangeStatus));
				while (itemStartIndex < fieldEndIndex)
				{
					unsigned short  itemId;
					std::string value;
					int sohIndex;
					if (StepUtility::GetNext(buff, itemStartIndex, fieldEndIndex, itemId, value, sohIndex))
					{
						switch (itemId)
						{
						case Items::FieldStart:
						case Items::FieldEnd:
							break;
						case Items::ExchangeId:
						{
							if (value.length() >= sizeof(RtnExchangeStatus->ExchangeId))
							{
								WriteLog(LogLevel::Warning, "ExchangeId Out Of Range. Length:%zu, Capacity:%zu", value.length(), sizeof(RtnExchangeStatus->ExchangeId) - 1);
								return false;
							}
							memcpy(RtnExchangeStatus->ExchangeId, value.c_str(), value.length());
							break;
						}
						case Items::ExchangeDate:
						{
							if (value.length() >= sizeof(RtnExchangeStatus->ExchangeDate))
							{
								WriteLog(LogLevel::Warning, "ExchangeDate Out Of Range. Length:%zu, Capacity:%zu", value.length(), sizeof(RtnExchangeStatus->ExchangeDate) - 1);
								return false;
							}
							memcpy(RtnExchangeStatus->ExchangeDate, value.c_str(), value.length());
							break;
						}
						case Items::ExchangeStatus:
						{
							if (!StepUtility::ParseEnum(value, RtnExchangeStatus->ExchangeStatus))
							{
								WriteLog(LogLevel::Warning, "ExchangeStatus Out Of Range. Value:%s", value.c_str());
								return false;
							}
							break;
						}
						default:
							WriteLog(LogLevel::Warning, "Unexpected ItemId:0x%X for RtnExchangeStatusField FieldId:0x%X, Please Check ApiVersion.", itemId, fieldId);
							return false;
						}
						itemStartIndex = sohIndex + 1;
					}
					else
					{
						WriteLog(LogLevel::Warning, "GetNext Failed For RtnExchangeStatusPackage FieldId:0x%X", fieldId);
						return false;
					}
				}
				break;
			}
			default:
				WriteLog(LogLevel::Warning, "Unexpected FieldId:0x%X, Please Check Api Version.", fieldId);
				return false;
			}
			startIndex = fieldEndIndex;
		}
		else
		{
			WriteLog(LogLevel::Warning, "GetNextFieldZone Failed For RtnExchangeStatusPackage");
			return false;
		}
	}
	return true;
}
